async def execute(req_id):
    """Hämta specifikt krav."""
    return env['ai.coworker'].prd_requirement_get(int(req_id))

async def execute(req_id, status):
    """Sätt status på krav."""
    return env['ai.coworker'].prd_requirement_set_status(int(req_id), str(status))

async def execute(func_id):
    """Hämta funktion med vytyper."""
    return env['ai.coworker'].prd_function_get(int(func_id))

async def execute(prd_id, design_text):
    """Spara moduldesign som plan."""
    return env['ai.coworker'].prd_module_design(int(prd_id), str(design_text))
